function(container, apiUrl, tables) {
  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aiLogic || {};

  // 初期化処理
  const today = new Date().toISOString().split('T')[0];
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
  const oneYearAgoStr = oneYearAgo.toISOString().split('T')[0];

  // デフォルト値設定
  const learningStartDate = container.querySelector('#learning-start-date');
  const learningEndDate = container.querySelector('#learning-end-date');
  const predictionStartDate = container.querySelector('#prediction-start-date');
  const predictionEndDate = container.querySelector('#prediction-end-date');

  if (learningStartDate) learningStartDate.value = oneYearAgoStr;
  if (learningEndDate) learningEndDate.value = today;

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toISOString().split('T')[0];
  if (predictionStartDate) predictionStartDate.value = tomorrowStr;

  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  const nextWeekStr = nextWeek.toISOString().split('T')[0];
  if (predictionEndDate) predictionEndDate.value = nextWeekStr;

  // 店舗データの読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeSelect = container.querySelector('#store-select');
      if (stores && storeSelect) {
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement('option');
            option.value = store.店舗ID;
            option.textContent = `${store.店舗コード} - ${store.店舗名}`;
            storeSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      window.aivicNotify.error('店舗データの読み込みに失敗しました: ' + error.message);
    }
  }

  // 商品カテゴリの読み込み
  async function loadProductCategories() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const categoryContainer = container.querySelector('#category-checkboxes');
      if (products && categoryContainer) {
        const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
        categories.forEach(categoryId => {
          const label = document.createElement('label');
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.value = categoryId;
          checkbox.name = 'product-categories';
          label.appendChild(checkbox);
          label.appendChild(document.createTextNode(`カテゴリ ${categoryId.substring(0, 8)}`));
          categoryContainer.appendChild(label);
        });
      }
    } catch (error) {
      window.aivicNotify.error('商品カテゴリの読み込みに失敗しました: ' + error.message);
    }
  }

  // 学習データ収集処理
  async function handleDataCollection() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const startDate = learningStartDate?.value;
      const endDate = learningEndDate?.value;

      if (!storeId || !startDate || !endDate) {
        window.aivicNotify.error('店舗と期間を選択してください');
        return;
      }

      // 売上データ収集
      const salesData = await collectSalesData(storeId, startDate, endDate);

      // 商品別・店舗別分類
      const productClassified = classifySalesDataByProduct(salesData);
      const storeClassified = classifySalesDataByStore(salesData);

      // 有効データフィルタリング
      const validData = filterValidProductData(productClassified);

      // 外部データ収集
      const weatherData = await collectWeatherData(startDate, endDate);
      const eventData = await collectEventData(startDate, endDate);
      const seasonalData = collectSeasonalData(startDate, endDate);

      // 結果表示
      const resultArea = container.querySelector('#data-collection-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>データ収集結果</h4>
          <p>売上データ: ${salesData.length}件</p>
          <p>有効商品データ: ${validData.length}件</p>
          <p>気象データ: ${weatherData.length}件</p>
          <p>イベントデータ: ${eventData.length}件</p>
          <p>季節データ: ${seasonalData.length}件</p>
        `;
      }

      window.aivicNotify.success('データ収集が完了しました');
    } catch (error) {
      window.aivicNotify.error('データ収集に失敗しました: ' + error.message);
    }
  }

  // 相関分析処理
  async function handleCorrelationAnalysis() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const startDate = learningStartDate?.value;
      const endDate = learningEndDate?.value;

      if (!storeId || !startDate || !endDate) {
        window.aivicNotify.error('店舗と期間を選択してください');
        return;
      }

      // データ収集
      const salesData = await collectSalesData(storeId, startDate, endDate);
      const weatherData = await collectWeatherData(startDate, endDate);
      const eventData = await collectEventData(startDate, endDate);
      const seasonalData = collectSeasonalData(startDate, endDate);

      // 相関分析実行
      const weatherCorr = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorr = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonCorr = analyzeCorrelationSalesSeason(salesData, seasonalData);

      // 結果表示
      const resultArea = container.querySelector('#correlation-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>相関分析結果</h4>
          <p>売上-気象相関: ${weatherCorr.correlation?.toFixed(3) || 'N/A'}</p>
          <p>売上-イベント相関: ${eventCorr.correlation?.toFixed(3) || 'N/A'}</p>
          <p>売上-季節相関: ${seasonCorr.correlation?.toFixed(3) || 'N/A'}</p>
        `;
      }

      window.aivicNotify.success('相関分析が完了しました');
    } catch (error) {
      window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
    }
  }

  // 履歴比較処理
  async function handleHistoricalComparison() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const startDate = learningStartDate?.value;
      const endDate = learningEndDate?.value;

      if (!storeId || !startDate || !endDate) {
        window.aivicNotify.error('店舗と期間を選択してください');
        return;
      }

      // 期間検証
      const isValidPeriod = validateComparisonPeriod(startDate, endDate);
      if (!isValidPeriod) {
        window.aivicNotify.error('比較期間が無効です');
        return;
      }

      // 現在データ収集
      const currentData = await collectSalesData(storeId, startDate, endDate);

      // 履歴比較実行
      const comparisonResult = await compareWithHistoricalData(currentData, storeId);

      // 代替比較データ検索
      const alternativeData = await findAlternativeComparisonData(storeId, startDate, endDate);

      // 結果表示
      const resultArea = container.querySelector('#historical-comparison-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>履歴比較結果</h4>
          <p>比較対象期間: ${comparisonResult.comparisonPeriod || 'N/A'}</p>
          <p>売上変化率: ${comparisonResult.changeRate?.toFixed(2) || 'N/A'}%</p>
          <p>代替データ件数: ${alternativeData.length}件</p>
        `;
      }

      window.aivicNotify.success('履歴比較が完了しました');
    } catch (error) {
      window.aivicNotify.error('履歴比較に失敗しました: ' + error.message);
    }
  }

  // 需要予測実行処理
  async function handlePredictionExecution() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const predStart = predictionStartDate?.value;
      const predEnd = predictionEndDate?.value;
      const selectedCategories = Array.from(container.querySelectorAll('input[name="product-categories"]:checked')).map(cb => cb.value);

      if (!storeId || !predStart || !predEnd) {
        window.aivicNotify.error('店舗と予測期間を選択してください');
        return;
      }

      // 学習データ収集
      const learningStart = learningStartDate?.value;
      const learningEnd = learningEndDate?.value;
      const salesData = await collectSalesData(storeId, learningStart, learningEnd);

      // 予測処理（簡易実装）
      const filteredData = selectedCategories.length > 0 
        ? salesData.filter(data => selectedCategories.includes(data.商品カテゴリID))
        : salesData;

      const avgSales = filteredData.reduce((sum, data) => sum + (data.売上数量 || 0), 0) / filteredData.length;

      // 結果表示
      const resultArea = container.querySelector('#prediction-result');
      if (resultArea) {
        resultArea.innerHTML = `
          <h4>需要予測結果</h4>
          <p>予測期間: ${predStart} ～ ${predEnd}</p>
          <p>予測平均売上: ${avgSales?.toFixed(0) || 0}個/日</p>
          <p>対象商品カテゴリ: ${selectedCategories.length || '全て'}</p>
        `;
      }

      window.aivicNotify.success('需要予測が完了しました');
    } catch (error) {
      window.aivicNotify.error('需要予測に失敗しました: ' + error.message);
    }
  }

  // イベントハンドラー設定
  const dataCollectionBtn = container.querySelector('#data-collection-btn');
  if (dataCollectionBtn) {
    dataCollectionBtn.addEventListener('click', handleDataCollection);
  }

  const correlationBtn = container.querySelector('#correlation-analysis-btn');
  if (correlationBtn) {
    correlationBtn.addEventListener('click', handleCorrelationAnalysis);
  }

  const historicalBtn = container.querySelector('#historical-comparison-btn');
  if (historicalBtn) {
    historicalBtn.addEventListener('click', handleHistoricalComparison);
  }

  const predictionBtn = container.querySelector('#prediction-execution-btn');
  if (predictionBtn) {
    predictionBtn.addEventListener('click', handlePredictionExecution);
  }

  // 初期データ読み込み
  loadStores();
  loadProductCategories();
}
